using System.Text.Json.Serialization;
using Saldo360.Api.Authentication;
using Saldo360.Application.Recurrences;
using Saldo360.Domain.Common;

namespace Saldo360.Api.Recurrences;

public static class FinancialRecurrenceEndpoints
{
    public static IEndpointRouteBuilder MapFinancialRecurrenceEndpoints(this IEndpointRouteBuilder app)
    {
        var g=app.MapGroup("/api/financial-workspaces/{workspaceId:guid}/recurrences").RequireAuthorization();
        g.MapGet("/",List); g.MapPost("/",Create).AddEndpointFilter<ValidateCsrfTokenFilter>(); g.MapGet("/{id:guid}",Get); g.MapPut("/{id:guid}",Update).AddEndpointFilter<ValidateCsrfTokenFilter>();
        g.MapPost("/{id:guid}/pause",(Guid f,Guid id,CurrentUser u,FinancialRecurrenceService s,CancellationToken ct)=>Change(f,id,u,s,"pause",ct)).AddEndpointFilter<ValidateCsrfTokenFilter>();
        g.MapPost("/{id:guid}/resume",(Guid f,Guid id,CurrentUser u,FinancialRecurrenceService s,CancellationToken ct)=>Change(f,id,u,s,"resume",ct)).AddEndpointFilter<ValidateCsrfTokenFilter>();
        g.MapPost("/{id:guid}/end",(Guid f,Guid id,CurrentUser u,FinancialRecurrenceService s,CancellationToken ct)=>Change(f,id,u,s,"end",ct)).AddEndpointFilter<ValidateCsrfTokenFilter>();
        g.MapDelete("/{id:guid}", (Guid f,Guid id,CurrentUser u,FinancialRecurrenceService s,CancellationToken ct)=>Change(f,id,u,s,"archive",ct)).AddEndpointFilter<ValidateCsrfTokenFilter>();
        g.MapGet("/{id:guid}/occurrences",Occurrences);
        g.MapPost("/{id:guid}/materialize",Materialize).AddEndpointFilter<ValidateCsrfTokenFilter>();
        g.MapGet("/{id:guid}/materializations",Materializations);
        return app;
    }
    private static async Task<IResult> Create(Guid workspaceId,RecurrenceRequest? request,CurrentUser user,FinancialRecurrenceService service,CancellationToken ct){if(await user.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();var r=await service.CreateAsync(workspaceId,uid,ToInput(request),ct);return Result(r,x=>Results.Created($"/api/financial-workspaces/{workspaceId}/recurrences/{x.Id}",RecurrenceResponse.From(x)));}
    private static async Task<IResult> Get(Guid workspaceId,Guid id,CurrentUser user,FinancialRecurrenceService service,CancellationToken ct){if(await user.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();var r=await service.GetAsync(workspaceId,id,uid,ct);return r is null?Results.NotFound():Results.Ok(RecurrenceResponse.From(r));}
    private static async Task<IResult> List(Guid workspaceId,bool? includeArchived,CurrentUser user,FinancialRecurrenceService service,CancellationToken ct){if(await user.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();var r=await service.ListAsync(workspaceId,uid,includeArchived??false,ct);return r.NotFound?Results.NotFound():Results.Ok(r.Items!.Select(RecurrenceResponse.From));}
    private static async Task<IResult> Update(Guid workspaceId,Guid id,RecurrenceRequest? request,CurrentUser user,FinancialRecurrenceService service,CancellationToken ct){if(await user.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();return Result(await service.UpdateAsync(workspaceId,id,uid,ToInput(request),ct),x=>Results.Ok(RecurrenceResponse.From(x)));}
    private static async Task<IResult> Change(Guid workspaceId,Guid id,CurrentUser user,FinancialRecurrenceService service,string operation,CancellationToken ct){if(await user.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();return Result(await service.ChangeAsync(workspaceId,id,uid,operation,ct),x=>Results.Ok(RecurrenceResponse.From(x)));}
    private static async Task<IResult> Occurrences(Guid workspaceId,Guid id,string? from,string? through,CurrentUser user,FinancialRecurrenceService service,CancellationToken ct){if(await user.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();var errors=new Dictionary<string,string[]>();var f=IsoDateQuery.Parse(from,"from",errors);var t=IsoDateQuery.Parse(through,"through",errors);if(f is null)errors["from"]=["Informe a data inicial no formato yyyy-MM-dd."];if(t is null)errors["through"]=["Informe a data final no formato yyyy-MM-dd."];if(errors.Count>0)return Results.ValidationProblem(errors);var r=await service.OccurrencesAsync(workspaceId,id,uid,f!.Value,t!.Value,ct);if(r.NotFound)return Results.NotFound();if(r.Error is not null)return Results.ValidationProblem(new Dictionary<string,string[]>{{"period",[r.Error]}});return Results.Ok(r.Items!.Select(x=>new OccurrenceResponse(x.RecurrenceId,x.Sequence,x.Date,Money.Format(x.Amount),x.Description,x.Type,x.IsEstimated,x.AccountId,x.CategoryId,x.CreditCardId)));}
    private static async Task<IResult> Materialize(Guid workspaceId,Guid id,MaterializeRequest? request,CurrentUser user,FinancialRecurrenceService service,CancellationToken ct){if(await user.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();var errors=new Dictionary<string,string[]>();var from=IsoDateQuery.Parse(request?.From,"from",errors);var through=IsoDateQuery.Parse(request?.Through,"through",errors);if(errors.Count>0||from is null||through is null){if(from is null)errors["from"]=["Informe from no formato yyyy-MM-dd."];if(through is null)errors["through"]=["Informe through no formato yyyy-MM-dd."];return Results.ValidationProblem(errors);}var result=await service.MaterializeAsync(workspaceId,id,uid,from,through,ct);if(result.NotFound)return Results.NotFound();if(result.Errors is not null)return Results.ValidationProblem(result.Errors);if(result.Conflict is not null)return Results.Conflict(new{title=result.Conflict});var value=result.Result!;return Results.Ok(new MaterializationResponse(value.RecurrenceId,value.CreatedCount,value.ExistingCount,value.Items.Select(MaterializationItemResponse.From).ToList()));}
    private static async Task<IResult> Materializations(Guid workspaceId,Guid id,string? from,string? through,CurrentUser user,FinancialRecurrenceService service,CancellationToken ct){if(await user.GetUserIdAsync(ct) is not{ } uid)return Results.Unauthorized();var errors=new Dictionary<string,string[]>();var f=IsoDateQuery.Parse(from,"from",errors);var t=IsoDateQuery.Parse(through,"through",errors);if(f is null)errors["from"]=["Informe from no formato yyyy-MM-dd."];if(t is null)errors["through"]=["Informe through no formato yyyy-MM-dd."];if(errors.Count>0)return Results.ValidationProblem(errors);var result=await service.MaterializationsAsync(workspaceId,id,uid,f,t,ct);if(result.NotFound)return Results.NotFound();if(result.Error is not null)return Results.ValidationProblem(new Dictionary<string,string[]>{{"period",[result.Error]}});return Results.Ok(result.Items!.Select(MaterializationViewResponse.From));}
    private static IResult Result(RecurrenceOperationResult r,Func<RecurrenceDto,IResult> ok)=>r.Access switch{RecurrenceAccess.NotFound=>Results.NotFound(),RecurrenceAccess.Invalid=>Results.ValidationProblem(r.Errors!),RecurrenceAccess.Conflict=>Results.Problem(statusCode:409,title:r.Message),_=>ok(r.Recurrence!)};
    private static RecurrenceInput ToInput(RecurrenceRequest? x)=>new(x?.AccountId,x?.CategoryId,x?.Type,x?.Description,x?.Amount,x?.IsEstimated??false,x?.Frequency,x?.Interval,x?.StartDate,x?.EndDate,x?.OccurrenceCount,x?.DayOfMonth,x?.CreditCardId);
}

[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record RecurrenceRequest(Guid? AccountId,Guid? CategoryId,string? Type,string? Description,decimal? Amount,bool IsEstimated,string? Frequency,int? Interval,DateOnly? StartDate,DateOnly? EndDate,int? OccurrenceCount,int? DayOfMonth,Guid? CreditCardId = null);
public sealed record RecurrenceResponse(Guid Id,Guid WorkspaceId,Guid? AccountId,Guid CategoryId,string Type,string Description,string Amount,bool IsEstimated,string Frequency,int Interval,DateOnly StartDate,DateOnly? EndDate,int? OccurrenceCount,int DayOfMonth,string Status,string Currency,DateTimeOffset CreatedAt,DateTimeOffset UpdatedAt,DateTimeOffset? ArchivedAt,Guid? CreditCardId = null)
{public static RecurrenceResponse From(RecurrenceDto x)=>new(x.Id,x.WorkspaceId,x.AccountId,x.CategoryId,x.Type.ToString(),x.Description,Money.Format(x.Amount),x.IsEstimated,x.Frequency.ToString(),x.Interval,x.StartDate,x.EndDate,x.OccurrenceCount,x.DayOfMonth,x.Status.ToString(),x.Currency,x.CreatedAt,x.UpdatedAt,x.ArchivedAt,x.CreditCardId);}
public sealed record OccurrenceResponse(Guid RecurrenceId,int Sequence,DateOnly Date,string Amount,string Description,Saldo360.Domain.Categories.CategoryType Type,bool IsEstimated,Guid? AccountId,Guid CategoryId,Guid? CreditCardId = null);
public sealed record MaterializeRequest(string? From,string? Through);
public sealed record MaterializationResponse(Guid RecurrenceId,int CreatedCount,int ExistingCount,IReadOnlyList<MaterializationItemResponse> Items);
public sealed record MaterializationItemResponse(int OccurrenceNumber,DateOnly ScheduledDate,Guid? PlannedTransactionId,DateOnly? PlannedDate,string? Amount,string? Status,string Result,Guid? CreditCardPurchaseId = null)
{ public static MaterializationItemResponse From(MaterializationItemDto x)=>new(x.OccurrenceNumber,x.ScheduledDate,x.PlannedTransactionId,x.PlannedDate,x.Amount is { } amount?Money.Format(amount):null,x.Status?.ToString(),x.Result,x.CreditCardPurchaseId); }
public sealed record MaterializationViewResponse(int OccurrenceNumber,DateOnly ScheduledDate,Guid? PlannedTransactionId,DateOnly? PlannedDate,string? Amount,string? Status,Guid? CreditCardPurchaseId = null)
{ public static MaterializationViewResponse From(MaterializationQueryItem x)=>new(x.OccurrenceNumber,x.ScheduledDate,x.PlannedTransactionId,x.PlannedDate,x.Amount is { } amount?Money.Format(amount):null,x.Status?.ToString(),x.CreditCardPurchaseId); }
